import { useState } from "react";

export function ProductPage({ product }: { product: Product }) {
  const [size, setSize] = useState("M");

  // Runs on every render: picking a size logs another "view"
  track("product_view", product.id);
  // A DOM write from a render React may repeat or discard
  document.title = product.name;

  return (
    <>
      <SizePicker value={size} onChange={setSize} />
      <button onClick={() => addToCart(product.id, size)}>Add to cart</button>
    </>
  );
}

import { useEffect, useState } from "react";

export function ProductPage({ product }: { product: Product }) {
  const [size, setSize] = useState("M");

  // After commit, once per product: syncing with the outside world
  useEffect(() => {
    track("product_view", product.id);
  }, [product.id]);

  function handleAdd() {
    track("add_to_cart", product.id); // caused by a click, so it lives here
    addToCart(product.id, size);
  }

  return (
    <>
      <title>{product.name}</title>
      <SizePicker value={size} onChange={setSize} />
      <button onClick={handleAdd}>Add to cart</button>
    </>
  );
}

