type Player = { id: string; name: string; score: number };

export function Leaderboard({ players }: { players: Player[] }) {
  // players.sort(...) would reorder the parent's array in place, mid-render.
  // toSorted() returns a copy created in this render, which is yours to change.
  const ranked = players.toSorted((a, b) => b.score - a.score);
  return <ol>{ranked.map((p) => <li key={p.id}>{p.name}</li>)}</ol>;
}
